package java.util;
public abstract class AbstractMap<K,V> implements Map<K,V> { protected AbstractMap(){} public int size(){return entrySet().size();} public boolean isEmpty(){return size()==0;} public boolean containsKey(Object k){for(Entry<K,V> e:entrySet())if(Objects.equals(k,e.getKey()))return true;return false;} public boolean containsValue(Object v){for(Entry<K,V> e:entrySet())if(Objects.equals(v,e.getValue()))return true;return false;} public V get(Object k){for(Entry<K,V> e:entrySet())if(Objects.equals(k,e.getKey()))return e.getValue();return null;} public V put(K k,V v){throw new UnsupportedOperationException();} public V remove(Object k){Iterator<Entry<K,V>> i=entrySet().iterator();while(i.hasNext()){Entry<K,V> e=i.next();if(Objects.equals(k,e.getKey())){V v=e.getValue();i.remove();return v;}}return null;} public void putAll(Map<? extends K,? extends V> m){for(Entry<? extends K,? extends V> e:m.entrySet())put(e.getKey(),e.getValue());} public void clear(){entrySet().clear();} public abstract Set<Entry<K,V>> entrySet(); public Set<K> keySet(){return new AbstractSet<K>(){public int size(){return AbstractMap.this.size();} public void clear(){AbstractMap.this.clear();} public boolean contains(Object k){return containsKey(k);} public Iterator<K> iterator(){final Iterator<Entry<K,V>> i=entrySet().iterator();return new Iterator<K>(){public boolean hasNext(){return i.hasNext();}public K next(){return i.next().getKey();}public void remove(){i.remove();}};}};} public Collection<V> values(){return new AbstractCollection<V>(){public int size(){return AbstractMap.this.size();}public void clear(){AbstractMap.this.clear();}public Iterator<V> iterator(){final Iterator<Entry<K,V>> i=entrySet().iterator();return new Iterator<V>(){public boolean hasNext(){return i.hasNext();}public V next(){return i.next().getValue();}public void remove(){i.remove();}};}};} public int hashCode(){return entrySet().hashCode();} public boolean equals(Object o){if(o==this)return true;if(!(o instanceof Map))return false;Map<?,?> m=(Map<?,?>)o;if(m.size()!=size())return false;for(Entry<K,V> e:entrySet()){Object k=e.getKey(),v=e.getValue();if(!Objects.equals(v,m.get(k))||(v==null&&!m.containsKey(k)))return false;}return true;} public String toString(){StringBuilder b=new StringBuilder("{");Iterator<Entry<K,V>> i=entrySet().iterator();while(i.hasNext()){Entry<K,V> e=i.next();Object k=e.getKey(),v=e.getValue();b.append(k==this?"(this Map)":String.valueOf(k)).append('=').append(v==this?"(this Map)":String.valueOf(v));if(i.hasNext())b.append(", ");}return b.append('}').toString();} public static class SimpleEntry<K,V> implements Entry<K,V>,java.io.Serializable {private final K k;private V v;public SimpleEntry(K k,V v){this.k=k;this.v=v;}public SimpleEntry(Entry<? extends K,? extends V> e){this(e.getKey(),e.getValue());}public K getKey(){return k;}public V getValue(){return v;}public V setValue(V v){V old=this.v;this.v=v;return old;}public boolean equals(Object o){if(!(o instanceof Entry))return false;Entry<?,?> e=(Entry<?,?>)o;return Objects.equals(k,e.getKey())&&Objects.equals(v,e.getValue());}public int hashCode(){return Objects.hashCode(k)^Objects.hashCode(v);}public String toString(){return k+"="+v;}} public static class SimpleImmutableEntry<K,V> extends SimpleEntry<K,V> {public SimpleImmutableEntry(K k,V v){super(k,v);}public SimpleImmutableEntry(Entry<? extends K,? extends V> e){super(e);}public V setValue(V v){throw new UnsupportedOperationException();}} }
